# Per-user MFA has no v1.0 cmdlet: the state lives in the beta API (users/{id}/authentication/requirements)
Install-Module Microsoft.Graph.Users, Microsoft.Graph.Beta.Identity.SignIns -Scope CurrentUser
Connect-MgGraph -Scopes 'User.Read.All', 'Policy.ReadWrite.AuthenticationMethod' -NoWelcome

# 1. who still has per-user MFA (enabled or enforced)
$left = Get-MgUser -All -Property Id, UserPrincipalName | ForEach-Object {
    $state = (Get-MgBetaUserAuthenticationRequirement -UserId $_.Id).PerUserMfaState
    if ($state -ne 'disabled') { [pscustomobject]@{ UPN = $_.UserPrincipalName; Id = $_.Id; State = $state } }
}
$left | Format-Table UPN, State
"$(@($left).Count) users with per-user MFA"

# 2. only when Security defaults or a Conditional Access policy requires MFA for these users
$left | ForEach-Object {
    Update-MgBetaUserAuthenticationRequirement -UserId $_.Id -BodyParameter @{ perUserMfaState = 'disabled' } -WhatIf
}   # read the list, then run again without -WhatIf
